package thaumcraft.test;
import java.util.*;
import com.mojang.authlib.GameProfile;
import net.minecraft.core.*;
import net.minecraft.core.component.DataComponents;
import net.minecraft.nbt.*;
import net.minecraft.server.level.*;
import net.minecraft.world.*;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.item.*;
import net.minecraft.world.item.context.UseOnContext;
import net.minecraft.world.level.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.storage.*;
import net.minecraft.world.phys.*;
import net.minecraft.util.ProblemReporter;
import net.minecraftforge.eventbus.api.listener.SubscribeEvent;
import net.minecraftforge.event.server.ServerStartedEvent;
import net.minecraftforge.fml.common.Mod;
import thaumcraft.alchemy.*;
import thaumcraft.banners.*;
@Mod.EventBusSubscriber(modid="thaumcraft")
public final class BannerProbe {
 static final List<ItemEntity> SPAWNED=new ArrayList<>();
 @SubscribeEvent public static void spawned(net.minecraftforge.event.entity.EntityJoinLevelEvent e){if(System.getProperty("thaumcraft.bookProbe","").equals("banner-write")&&e.getEntity() instanceof ItemEntity item&&item.distanceToSqr(Vec3.atCenterOf(P))<16)SPAWNED.add(item);}
 public static final BlockPos P=new BlockPos(68008,160,8),SAVED=P.east(40);
 public static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
 public static void set(ServerLevel l,BlockPos p,net.minecraft.world.level.block.state.BlockState state){l.getChunkAt(p);l.setBlockAndUpdate(p,state);}
 public static AspectBannerEntity banner(ServerLevel l,BlockPos at,DyeColor d,boolean wall,int rotation){if(l.getBlockEntity(at)!=null)l.removeBlock(at,false);var block=d==null?BannerContent.CULT.get():BannerContent.COLOURS.get(d).get();var state=block.defaultBlockState().setValue(AspectBannerBlock.WALL,wall).setValue(AspectBannerBlock.ROTATION,rotation);set(l,AspectBannerBlock.support(state,at),Blocks.STONE.defaultBlockState());set(l,at,state);return (AspectBannerEntity)l.getBlockEntity(at);}
 static void use(ServerPlayer p,BlockPos at,Direction face){var hit=new BlockHitResult(Vec3.atCenterOf(at).add(face.getStepX()*.5,face.getStepY()*.5,face.getStepZ()*.5),face,at,false);p.gameMode.useItemOn(p,p.level(),p.getMainHandItem(),InteractionHand.MAIN_HAND,hit);}
 static void clean(ServerLevel l,BlockPos at){SPAWNED.forEach(ItemEntity::discard);SPAWNED.clear();l.removeBlock(at,false);for(var item:l.getEntitiesOfClass(ItemEntity.class,new AABB(at).inflate(3)))item.discard();}
 static void place(ServerLevel l,ServerPlayer p){for(var d:DyeColor.values()){clean(l,P);set(l,P.below(),Blocks.STONE.defaultBlockState());p.setPos(P.getX()+2,P.getY(),P.getZ()+2);p.setYRot(d.getId()*22.5F);p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(BannerContent.COLOURS.get(d).get(),2));use(p,P.below(),Direction.UP);check(l.getBlockEntity(P) instanceof AspectBannerEntity,"Native floor placement failed "+d);var state=l.getBlockState(P);check(!state.getValue(AspectBannerBlock.WALL)&&state.getValue(AspectBannerBlock.ROTATION)==((d.getId()+8)&15),"Floor rotation wrong "+d);check(p.getMainHandItem().getCount()==1,"Floor placement not paid");}
 for(var face:Direction.Plane.HORIZONTAL){clean(l,P);set(l,P.relative(face.getOpposite()),Blocks.STONE.defaultBlockState());p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(BannerContent.COLOURS.get(DyeColor.PURPLE).get()));use(p,P.relative(face.getOpposite()),face);check(l.getBlockEntity(P) instanceof AspectBannerEntity,"Native wall placement failed "+face);var state=l.getBlockState(P);check(state.getValue(AspectBannerBlock.WALL)&&AspectBannerBlock.facing(state)==face,"Wall direction wrong");}
 clean(l,P);set(l,P.above(),Blocks.STONE.defaultBlockState());p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(BannerContent.COLOURS.get(DyeColor.WHITE).get()));use(p,P.above(),Direction.DOWN);check(l.getBlockEntity(P)==null&&p.getMainHandItem().getCount()==1,"Ceiling accepted or consumed banner");l.removeBlock(P.above(),false);thaumcraft.Thaumcraft.LOGGER.info("BANNER72_PLACEMENT_OK: 16 paid floor rotations, four native wall placements, ceiling rejected");}
 static void painting(ServerLevel l,ServerPlayer p){var b=banner(l,P,DyeColor.BLUE,false,0);check(thaumcraft.alchemy.AspectResolver.item(l,new ItemStack(BannerContent.COLOURS.get(DyeColor.BLUE).get())).getOrDefault("alienis",0)>=5,"Original complex banner aspects missing");p.setPos(P.getX()+2,P.getY(),P.getZ()+2);for(var a:thaumcraft.crystals.CrystalAspects.COLORS.keySet()){p.setShiftKeyDown(false);p.setItemInHand(InteractionHand.MAIN_HAND,AlchemyContent.filled(AlchemyContent.PHIAL.get(),a,10));use(p,P,Direction.SOUTH);check(b.aspect().equals(a)&&p.getMainHandItem().isEmpty(),"Native painting not paid "+a);var pick=l.getBlockState(P).getCloneItemStack(l,P,false);check(pick.getOrDefault(BannerContent.ASPECT.get(),"").equals(a),"Native pick lost glyph");p.setItemInHand(InteractionHand.MAIN_HAND,AlchemyContent.filled(AlchemyContent.PHIAL.get(),a,10));use(p,P,Direction.SOUTH);check(p.getMainHandItem().getCount()==1,"Duplicate glyph consumed vial");}
 p.setShiftKeyDown(true);p.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);use(p,P,Direction.SOUTH);check(b.aspect().isEmpty(),"Sneak clear failed");p.setShiftKeyDown(false);p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(AlchemyContent.PHIAL.get()));use(p,P,Direction.SOUTH);check(b.aspect().isEmpty()&&p.getMainHandItem().getCount()==1,"Empty vial painted or consumed");p.setItemInHand(InteractionHand.MAIN_HAND,AlchemyContent.filled(AlchemyContent.PHIAL.get(),"ignis",1));use(p,P,Direction.SOUTH);check(b.aspect().isEmpty()&&p.getMainHandItem().getCount()==1,"Partial vial consumed");
 b=banner(l,P,null,false,0);p.setItemInHand(InteractionHand.MAIN_HAND,AlchemyContent.filled(AlchemyContent.PHIAL.get(),"ignis",10));use(p,P,Direction.SOUTH);check(b.aspect().isEmpty()&&p.getMainHandItem().getCount()==1,"Cult banner repainted");clean(l,P);thaumcraft.Thaumcraft.LOGGER.info("BANNER72_PAINT_OK: 37 real phial interactions, exact payment, pick, duplicate/invalid/partial rejection, clearing and immutable cult emblem");}
 static void drops(ServerLevel l,ServerPlayer p){for(boolean wall:new boolean[]{false,true}){clean(l,P);var b=banner(l,P,DyeColor.RED,wall,0);var painted=new ItemStack(BannerContent.COLOURS.get(DyeColor.RED).get());painted.set(BannerContent.ASPECT.get(),"aer");b.placeContents(painted);var state=l.getBlockState(P);set(l,AspectBannerBlock.support(state,P),Blocks.AIR.defaultBlockState());check(l.getBlockEntity(P)==null,"Lost support retained banner");var items=List.copyOf(SPAWNED);check(items.size()==1&&items.getFirst().getItem().getOrDefault(BannerContent.ASPECT.get(),"").equals("aer"),"Support drop missing/duplicated glyph wall="+wall+" drops="+items.stream().map(i->i.getItem().toString()+" glyph="+i.getItem().get(BannerContent.ASPECT.get())).toList()+" blockdrops="+l.getGameRules().get(net.minecraft.world.level.gamerules.GameRules.BLOCK_DROPS));items.getFirst().discard();}
 var b=banner(l,P,DyeColor.GREEN,false,0);var future=b.saveWithoutMetadata(l.registryAccess());var raw=new CompoundTag();raw.putInt("version",2);raw.putString("aspect","not_yet_known");raw.putString("future_payload","preserve me");future.put("banner",raw);b.loadWithComponents(TagValueInput.create(ProblemReporter.DISCARDING,l.registryAccess(),future));check(!b.supported(),"Unknown banner remains editable");p.setItemInHand(InteractionHand.MAIN_HAND,AlchemyContent.filled(AlchemyContent.PHIAL.get(),"aer",10));use(p,P,Direction.SOUTH);check(p.getMainHandItem().getCount()==1,"Unknown banner ate vial");var drop=Block.getDrops(b.getBlockState(),l,P,b).getFirst();var data=drop.get(DataComponents.BLOCK_ENTITY_DATA);check(data!=null&&data.copyTagWithoutId().getCompoundOrEmpty("banner").equals(raw),"Future data discarded");clean(l,P);b=banner(l,P,DyeColor.GREEN,false,0);check(data.loadInto(b,l.registryAccess())&&!b.supported(),"Future item re-placement lost data");clean(l,P);thaumcraft.Thaumcraft.LOGGER.info("BANNER72_DROPS_OK: real support loss drops once, wall/floor glyphs and opaque future item data");}
 static void portal(ServerLevel l){var center=P.south(32);for(var d:Direction.Plane.HORIZONTAL){var at=center.relative(d,6);set(l,at.below(),Blocks.STONE.defaultBlockState());set(l,at,Blocks.AIR.defaultBlockState());}var protectedAt=center.east(6);set(l,protectedAt,Blocks.DIAMOND_BLOCK.defaultBlockState());var portal=new thaumcraft.eldritch.EldritchMob(thaumcraft.eldritch.EldritchContent.TYPES.get(thaumcraft.eldritch.EldritchMob.Kind.PORTAL).get(),l,thaumcraft.eldritch.EldritchMob.Kind.PORTAL);portal.setPos(Vec3.atBottomCenterOf(center));portal.setNoGravity(true);for(int i=0;i<40;i++)portal.tick();for(var d:Direction.Plane.HORIZONTAL){var at=center.relative(d,6);check(d==Direction.EAST?l.getBlockState(at).is(Blocks.DIAMOND_BLOCK):l.getBlockState(at).is(BannerContent.CULT.get()),"Portal decoration overwrote protected block or did not spawn "+d);if(d!=Direction.EAST){check(AspectBannerBlock.facing(l.getBlockState(at))==d,"Cult banner not facing outward");l.removeBlock(at,false);}}portal.tick();check(!l.getBlockState(center.north(6)).is(BannerContent.CULT.get()),"Portal respawned harvested decorations");portal.discard();thaumcraft.Thaumcraft.LOGGER.info("BANNER72_CULT_OK: greater portal decorates at tick 40, faces outward, protects occupied blocks and does not respawn harvest");}
 static void write(ServerLevel l,ServerPlayer p){place(l,p);painting(l,p);drops(l,p);portal(l);var b=banner(l,SAVED,DyeColor.CYAN,true,12);var item=new ItemStack(BannerContent.COLOURS.get(DyeColor.CYAN).get());item.set(BannerContent.ASPECT.get(),"praecantatio");b.placeContents(item);thaumcraft.Thaumcraft.LOGGER.info("BANNER72_WRITE_OK");}
 static void read(ServerLevel l){l.getChunkAt(SAVED);var b=(AspectBannerEntity)l.getBlockEntity(SAVED);check(thaumcraft.alchemy.AspectResolver.item(l,new ItemStack(BannerContent.COLOURS.get(DyeColor.CYAN).get())).getOrDefault("alienis",0)>=5,"Original complex banner aspects missing after restart");check(b!=null&&b.supported()&&b.aspect().equals("praecantatio")&&b.getBlockState().getValue(AspectBannerBlock.WALL)&&b.getBlockState().getValue(AspectBannerBlock.ROTATION)==12,"Cold restart lost wall/banner glyph");var item=Block.getDrops(b.getBlockState(),l,SAVED,b).getFirst();check(item.getOrDefault(BannerContent.ASPECT.get(),"").equals("praecantatio"),"Restart drop lost glyph");var next=banner(l,SAVED.east(3),DyeColor.CYAN,false,0);next.placeContents(item);check(next.aspect().equals("praecantatio"),"Restart recollection lost glyph");thaumcraft.Thaumcraft.LOGGER.info("BANNER72_RESTART_OK: second JVM recovers wall, rotation, dye and glyph, then native loot and re-placement");}
 @SubscribeEvent public static void start(ServerStartedEvent e){var mode=System.getProperty("thaumcraft.bookProbe","");if(!Set.of("banner-write","banner-read").contains(mode))return;var l=e.getServer().overworld();e.getServer().tickRateManager().setFrozen(true);if(mode.endsWith("read"))read(l);else{e.getServer().setDifficulty(Difficulty.NORMAL,true);var p=new ServerPlayer(e.getServer(),l,new GameProfile(UUID.randomUUID(),"BannerProof"),ClientInformation.createDefault());new net.minecraft.server.network.ServerGamePacketListenerImpl(e.getServer(),new net.minecraft.network.Connection(net.minecraft.network.protocol.PacketFlow.SERVERBOUND),p,net.minecraft.server.network.CommonListenerCookie.createInitial(p.getGameProfile(),false)){@Override public void send(net.minecraft.network.protocol.Packet<?> packet){}@Override public void send(net.minecraft.network.protocol.Packet<?> packet,io.netty.channel.ChannelFutureListener listener){}};p.gameMode.changeGameModeForPlayer(GameType.SURVIVAL);p.setPos(P.getX()+2,P.getY(),P.getZ()+2);write(l,p);}e.getServer().halt(false);}
}
